const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const needles = ee.Geometry.Point([-114.6142, 34.8481]); // Needles, CA
  const phoenix = ee.Geometry.Point([-112.0740, 33.4484]); // Phoenix, AZ
  const date = '2017-06-21';

  // 2. Data Acquisition - MODIS Terra LST (daily coverage)
  const col = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select(['LST_Day_1km', 'QC_Day']);

  const colSize = await col.size().getInfo();
  console.log(`Images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No MODIS data for June 21, 2017');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get first image and apply QA mask
  const img = col.first();

  // Mask based on QA (keep only good quality pixels: bits 0-1 = 00)
  const qa = img.select('QC_Day');
  const mask = qa.bitwiseAnd(3).eq(0);
  const lstMasked = img.select('LST_Day_1km').updateMask(mask).multiply(0.02).subtract(273.15); // Convert to Celsius

  // 4. Calculate LST for both locations
  const needlesStats = await lstMasked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: needles,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const phoenixStats = await lstMasked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: phoenix,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  // Check pixel counts
  const needlesCount = await lstMasked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: needles.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const phoenixCount = await lstMasked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: phoenix.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const needlesLST = needlesStats.LST_Day_1km;
  const phoenixLST = phoenixStats.LST_Day_1km;
  const needlesPx = needlesCount.LST_Day_1km;
  const phoenixPx = phoenixCount.LST_Day_1km;

  console.log(`Needles LST: ${needlesLST !== null ? needlesLST.toFixed(2) : 'null'}°C, Pixels: ${needlesPx || 0}`);
  console.log(`Phoenix LST: ${phoenixLST !== null ? phoenixLST.toFixed(2) : 'null'}°C, Pixels: ${phoenixPx || 0}`);

  // 5. Validation & Final Answer
  if (needlesPx === 0 || phoenixPx === 0) {
    console.log('No valid pixels after QA masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (needlesLST === null || phoenixLST === null || isNaN(needlesLST) || isNaN(phoenixLST)) {
    console.log('Invalid LST calculation');
    console.log('<answer>C3</answer>');
    return;
  }

  if (needlesLST < -50 || needlesLST > 100 || phoenixLST < -50 || phoenixLST > 100) {
    console.log('LST out of reasonable range');
    console.log('<answer>C3</answer>');
    return;
  }

  if (needlesLST > phoenixLST) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
